pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {StaxLPStaking} from "../src/StaxLPStaking.sol";

contract InvMutTest is Test {
    StaxLPStaking c;

    function setUp() public {
        c = new StaxLPStaking(address(new __InvMutHandleStub()), address(new __InvMutHandleStub()));
    }

    function testFuzz_property(address newOwner) public {
        address before = c.owner();
        vm.prank(before);
        try c.transferOwnership(newOwner) {
            // ownership change attempted; rule must still hold
        } catch {
            // call reverted: ownership unchanged; rule must still hold
        }
        assertTrue(c.owner() != address(0), "owner must never be zero");
    }
}

